package com.travel.meomulkyung.itinerary.domain;
import com.travel.meomulkyung.region.domain.Region; import com.travel.meomulkyung.user.domain.User; import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor; import java.time.LocalDateTime;
@Entity @Table(name="user_stamps",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","region_id"})) @Getter @NoArgsConstructor public class UserStamp { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="user_stamp_id") private Long id; @ManyToOne(optional=false) @JoinColumn(name="user_id") private User user; @ManyToOne(optional=false) @JoinColumn(name="region_id") private Region region; @Column(nullable=false) private int visitCount; private LocalDateTime firstAwardedAt; private LocalDateTime lastVisitedAt; public UserStamp(User u,Region r){user=u;region=r;visitCount=1;firstAwardedAt=LocalDateTime.now();lastVisitedAt=firstAwardedAt;} public void visit(){visitCount++;lastVisitedAt=LocalDateTime.now();}}
